<?php
require_once '_bootstrap.php';require_admin_permission('reports.view');$db=admin_db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);try{$payment=$db->execute_query('SELECT id,status,transaction_reference FROM payments WHERE id=?',[$id])->fetch_assoc();if(!$payment)throw new RuntimeException('Transaction not found.');if(!in_array($payment['status'],['failed','cancelled'],true))throw new RuntimeException('Paid and refund records are permanent audit entries and cannot be deleted.');$db->execute_query('DELETE FROM payments WHERE id=?',[$id]);admin_audit($db,'delete_attempt','payment',(string)$id,(string)$payment['transaction_reference']);redirect_with_message('transactions.php','Unused payment attempt deleted.');}catch(Throwable $error){redirect_with_message('transactions.php',$error->getMessage());}}
$search=trim($_GET['q']??'');$status=trim($_GET['status']??'');$allowed=['paid','refunded','failed','cancelled','pending'];$clauses=[];$params=[];if($search!==''){$clauses[]='(p.transaction_reference LIKE ? OR b.booking_reference LIKE ? OR b.customer_name LIKE ? OR b.user_email LIKE ?)';$term='%'.$search.'%';$params=[$term,$term,$term,$term];}if(in_array($status,$allowed,true)){$clauses[]='p.status=?';$params[]=$status;}else $status='';$where=$clauses?' WHERE '.implode(' AND ',$clauses):'';$count=(int)$db->execute_query("SELECT COUNT(*) total FROM payments p JOIN bookings b ON b.id=p.booking_id$where",$params)->fetch_assoc()['total'];$pages=max(1,(int)ceil($count/15));$page=min(max(1,(int)($_GET['page']??1)),$pages);$offset=($page-1)*15;
$rows=$db->execute_query("SELECT p.*,b.booking_reference,b.customer_name,b.user_email,b.destination,b.payment_status,b.id booking_id,c.approved_refund,c.policy_name FROM payments p JOIN bookings b ON b.id=p.booking_id LEFT JOIN cancellation_requests c ON c.booking_id=b.id AND c.id=(SELECT MAX(c2.id) FROM cancellation_requests c2 WHERE c2.booking_id=b.id) $where ORDER BY p.created_at DESC,p.id DESC LIMIT 15 OFFSET $offset",$params);$summary=$db->query("SELECT COALESCE(SUM(CASE WHEN status='paid' THEN amount ELSE 0 END),0) collected,COALESCE(SUM(CASE WHEN status='refunded' THEN -amount ELSE 0 END),0) refunded,COALESCE(SUM(CASE WHEN status IN ('paid','refunded') THEN amount ELSE 0 END),0) net FROM payments")->fetch_assoc();$pageTitle='Transactions';include '_header.php';?>
<div class="page-head"><div><span>Payment and refund ledger</span><h1>Transactions</h1><p>Search by booking reference, transaction reference, customer, or email.</p></div></div><section class="metric-grid"><article class="metric"><i class="fa-solid fa-arrow-down"></i><span>Collected</span><strong><?php echo inr($summary['collected']);?></strong></article><article class="metric"><i class="fa-solid fa-rotate-left"></i><span>Refunded</span><strong><?php echo inr($summary['refunded']);?></strong></article><article class="metric"><i class="fa-solid fa-wallet"></i><span>Net revenue</span><strong><?php echo inr($summary['net']);?></strong></article></section>
<section class="panel"><div class="panel-head region-tools"><h2>Transaction register</h2><form class="search-form directory-tools" method="get"><input type="search" name="q" value="<?php echo e($search);?>" placeholder="Reference, customer, or email"><select name="status"><option value="">All transaction types</option><?php foreach($allowed as $value):?><option value="<?php echo $value;?>" <?php echo $status===$value?'selected':'';?>><?php echo ucfirst($value);?></option><?php endforeach;?></select><button class="primary-btn"><i class="fa-solid fa-magnifying-glass"></i> Search</button><a class="reset-btn" href="transactions.php"><i class="fa-solid fa-rotate-left"></i> Reset</a></form></div><div class="table-wrap"><table><thead><tr><th>References</th><th>Customer</th><th>Status</th><th>Amount</th><th>Refund details</th><th>Date</th><th>Actions</th></tr></thead><tbody><?php while($row=$rows->fetch_assoc()):?><tr><td><strong><?php echo e($row['transaction_reference']);?></strong><small><?php echo e($row['booking_reference']);?></small></td><td><?php echo e($row['customer_name']);?><small><?php echo e($row['user_email']);?></small></td><td><span class="pill"><?php echo e($row['status']);?></span><small><?php echo e(strtoupper(str_replace(['practice_','demo_','admin_'],'',$row['method'])));?></small></td><td class="<?php echo (float)$row['amount']<0?'amount-negative':'amount-positive';?>"><?php echo inr($row['amount']);?></td><td><?php if($row['status']==='refunded'):?>Approved: <?php echo inr($row['approved_refund']??-$row['amount']);?><small><?php echo e($row['policy_name']??'Cancellation refund');?></small><?php else:?>-<?php endif;?></td><td><?php echo e(date('d M Y, h:i A',strtotime($row['created_at'])));?></td><td><div class="action-row"><a class="icon-btn" href="booking-details.php?id=<?php echo (int)$row['booking_id'];?>" title="Full details"><i class="fa-solid fa-eye"></i></a><?php if(in_array($row['status'],['failed','cancelled'],true)):?><form method="post" onsubmit="return confirm('Delete this unused payment attempt?')"><?php echo csrf_input();?><input type="hidden" name="id" value="<?php echo (int)$row['id'];?>"><button class="icon-btn danger-icon" title="Delete unused attempt"><i class="fa-solid fa-trash"></i></button></form><?php endif;?></div></td></tr><?php endwhile;?></tbody></table></div><?php admin_pagination(['pages'=>$pages,'page'=>$page,'parameter'=>'page']);?></section><?php include '_footer.php';?>
